        function speakText(text, lang = 'de-DE') {
            if (!text) return;
            window.speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(text);
            utterance.lang = lang;
            utterance.rate = 0.95;

            if (availableVoices.length > 0) {
                if (lang.startsWith('en')) {
                    const preferredEnVoices = ['Samantha', 'Karen', 'Victoria', 'Google US English', 'Siri', 'Fiona', 'Moira'];
                    let selectedVoice = availableVoices.find(v => preferredEnVoices.some(p => v.name.includes(p)) && v.lang.startsWith('en'));
                    if (!selectedVoice) {
                        selectedVoice = availableVoices.find(v => v.lang.startsWith('en') && !v.name.includes('Fred') && !v.name.includes('Albert'));
                    }
                    if (selectedVoice) utterance.voice = selectedVoice;

                } else if (lang.startsWith('de')) {
                    const preferredDeVoices = ['Anna', 'Helena', 'Katrin', 'Marni', 'Google Deutsch', 'Viktor', 'Siri'];
                    let selectedVoice = availableVoices.find(v => preferredDeVoices.some(p => v.name.includes(p)) && v.lang.startsWith('de'));
                    if (!selectedVoice) {
                        selectedVoice = availableVoices.find(v => v.lang.startsWith('de'));
                    }
                    if (selectedVoice) utterance.voice = selectedVoice;
                }
            }

            window.speechSynthesis.speak(utterance);
        }

